-- =============================================================================
-- CivicGrant Lite - initial schema
--
-- Business rules live in the domain model. Constraints here are a safety net
-- (defence in depth), not the primary place where rules are enforced.
-- Identities live in Entra ID: users are referenced by their object id
-- (the "oid" claim), never stored as a local user table.
-- Ids are generated by the application (domain-generated identity).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Funding call: a time-boxed call for projects with a fixed budget envelope.
-- committed_amount is the sum of approved grants; version enables optimistic
-- locking so two simultaneous approvals cannot exceed the budget.
-- -----------------------------------------------------------------------------
CREATE TABLE funding_call (
    id                         UUID          PRIMARY KEY,
    reference                  VARCHAR(30)   NOT NULL,
    title_nl                   VARCHAR(200)  NOT NULL,
    title_fr                   VARCHAR(200)  NOT NULL,
    opens_at                   TIMESTAMPTZ   NOT NULL,
    closes_at                  TIMESTAMPTZ   NOT NULL,
    total_budget               NUMERIC(12,2) NOT NULL,
    committed_amount           NUMERIC(12,2) NOT NULL DEFAULT 0,
    max_amount_per_application NUMERIC(12,2) NOT NULL,
    version                    BIGINT        NOT NULL DEFAULT 0,
    created_at                 TIMESTAMPTZ   NOT NULL,

    CONSTRAINT uq_funding_call_reference UNIQUE (reference),
    CONSTRAINT ck_funding_call_period    CHECK (closes_at > opens_at),
    CONSTRAINT ck_funding_call_budget    CHECK (total_budget > 0),
    CONSTRAINT ck_funding_call_committed CHECK (committed_amount >= 0
                                                AND committed_amount <= total_budget),
    CONSTRAINT ck_funding_call_max       CHECK (max_amount_per_application > 0
                                                AND max_amount_per_application <= total_budget)
);

-- -----------------------------------------------------------------------------
-- Organisation: identified by its Belgian enterprise number (KBO/BCE),
-- stored as 10 digits without dots. The last two digits are a mod-97
-- checksum of the first eight.
-- -----------------------------------------------------------------------------
CREATE TABLE organisation (
    id                UUID         PRIMARY KEY,
    enterprise_number CHAR(10)     NOT NULL,
    name              VARCHAR(200) NOT NULL,
    legal_form        VARCHAR(30)  NOT NULL,
    created_at        TIMESTAMPTZ  NOT NULL,

    CONSTRAINT uq_organisation_enterprise_number UNIQUE (enterprise_number),
    CONSTRAINT ck_organisation_enterprise_number_format
        CHECK (enterprise_number ~ '^[01][0-9]{9}$'),
    CONSTRAINT ck_organisation_enterprise_number_checksum
        CHECK (97 - (LEFT(enterprise_number, 8)::BIGINT % 97) = RIGHT(enterprise_number, 2)::INT),
    CONSTRAINT ck_organisation_legal_form
        CHECK (legal_form IN ('VZW_ASBL', 'IVZW_AISBL', 'FOUNDATION', 'COMPANY', 'PUBLIC_BODY'))
);

-- -----------------------------------------------------------------------------
-- Grant application: the aggregate root of the workflow.
-- -----------------------------------------------------------------------------
CREATE TABLE grant_application (
    id                   UUID          PRIMARY KEY,
    reference            VARCHAR(30)   NOT NULL,
    funding_call_id      UUID          NOT NULL,
    organisation_id      UUID          NOT NULL,
    applicant_oid        VARCHAR(64)   NOT NULL,
    project_title        VARCHAR(200)  NOT NULL,
    project_description  TEXT          NOT NULL,
    requested_amount     NUMERIC(12,2) NOT NULL,
    total_project_budget NUMERIC(12,2) NOT NULL,
    language             CHAR(2)       NOT NULL,
    status               VARCHAR(20)   NOT NULL,
    submitted_at         TIMESTAMPTZ,
    version              BIGINT        NOT NULL DEFAULT 0,
    created_at           TIMESTAMPTZ   NOT NULL,
    updated_at           TIMESTAMPTZ   NOT NULL,

    CONSTRAINT uq_grant_application_reference UNIQUE (reference),
    CONSTRAINT fk_grant_application_call
        FOREIGN KEY (funding_call_id) REFERENCES funding_call (id),
    CONSTRAINT fk_grant_application_organisation
        FOREIGN KEY (organisation_id) REFERENCES organisation (id),
    CONSTRAINT ck_grant_application_status
        CHECK (status IN ('DRAFT', 'SUBMITTED', 'ASSESSED', 'APPROVED', 'REJECTED')),
    CONSTRAINT ck_grant_application_language
        CHECK (language IN ('nl', 'fr')),
    CONSTRAINT ck_grant_application_amounts
        CHECK (requested_amount > 0 AND requested_amount <= total_project_budget),
    CONSTRAINT ck_grant_application_submitted
        CHECK (status = 'DRAFT' OR submitted_at IS NOT NULL)
);

CREATE INDEX ix_grant_application_call         ON grant_application (funding_call_id);
CREATE INDEX ix_grant_application_organisation ON grant_application (organisation_id);
CREATE INDEX ix_grant_application_applicant    ON grant_application (applicant_oid);
CREATE INDEX ix_grant_application_status       ON grant_application (status, submitted_at);

-- -----------------------------------------------------------------------------
-- Supporting document: metadata only, the file itself lives in Blob Storage.
-- -----------------------------------------------------------------------------
CREATE TABLE supporting_document (
    id                   UUID         PRIMARY KEY,
    grant_application_id UUID         NOT NULL,
    blob_name            VARCHAR(300) NOT NULL,
    original_filename    VARCHAR(255) NOT NULL,
    content_type         VARCHAR(100) NOT NULL,
    size_bytes           BIGINT       NOT NULL,
    uploaded_by_oid      VARCHAR(64)  NOT NULL,
    uploaded_at          TIMESTAMPTZ  NOT NULL,

    CONSTRAINT uq_supporting_document_blob UNIQUE (blob_name),
    CONSTRAINT fk_supporting_document_application
        FOREIGN KEY (grant_application_id) REFERENCES grant_application (id) ON DELETE CASCADE,
    CONSTRAINT ck_supporting_document_type
        CHECK (content_type = 'application/pdf'),
    CONSTRAINT ck_supporting_document_size
        CHECK (size_bytes > 0 AND size_bytes <= 10485760)
);

CREATE INDEX ix_supporting_document_application ON supporting_document (grant_application_id);

-- -----------------------------------------------------------------------------
-- Assessment: one per application, recorded by a civil servant.
-- -----------------------------------------------------------------------------
CREATE TABLE assessment (
    id                   UUID          PRIMARY KEY,
    grant_application_id UUID          NOT NULL,
    assessor_oid         VARCHAR(64)   NOT NULL,
    eligible             BOOLEAN       NOT NULL,
    recommendation       VARCHAR(10)   NOT NULL,
    proposed_amount      NUMERIC(12,2),
    comment              TEXT          NOT NULL,
    assessed_at          TIMESTAMPTZ   NOT NULL,

    CONSTRAINT uq_assessment_application UNIQUE (grant_application_id),
    CONSTRAINT fk_assessment_application
        FOREIGN KEY (grant_application_id) REFERENCES grant_application (id),
    CONSTRAINT ck_assessment_recommendation
        CHECK (recommendation IN ('APPROVE', 'REJECT')),
    CONSTRAINT ck_assessment_consistency
        CHECK (
            (recommendation = 'APPROVE' AND eligible AND proposed_amount > 0)
         OR (recommendation = 'REJECT'  AND proposed_amount IS NULL)
        )
);

-- -----------------------------------------------------------------------------
-- Decision: one per application, taken by a decision maker.
-- Separation of duties (assessor <> decision maker) is enforced in the domain;
-- a cross-table rule like that does not belong in a CHECK constraint.
-- -----------------------------------------------------------------------------
CREATE TABLE decision (
    id                   UUID          PRIMARY KEY,
    grant_application_id UUID          NOT NULL,
    decision_maker_oid   VARCHAR(64)   NOT NULL,
    outcome              VARCHAR(10)   NOT NULL,
    granted_amount       NUMERIC(12,2),
    rejection_ground     VARCHAR(30),
    motivation           TEXT          NOT NULL,
    decided_at           TIMESTAMPTZ   NOT NULL,

    CONSTRAINT uq_decision_application UNIQUE (grant_application_id),
    CONSTRAINT fk_decision_application
        FOREIGN KEY (grant_application_id) REFERENCES grant_application (id),
    CONSTRAINT ck_decision_outcome
        CHECK (outcome IN ('APPROVED', 'REJECTED')),
    CONSTRAINT ck_decision_rejection_ground
        CHECK (rejection_ground IS NULL OR rejection_ground IN
               ('INELIGIBLE', 'BUDGET_EXHAUSTED', 'INCOMPLETE', 'INSUFFICIENT_QUALITY')),
    CONSTRAINT ck_decision_consistency
        CHECK (
            (outcome = 'APPROVED' AND granted_amount > 0 AND rejection_ground IS NULL)
         OR (outcome = 'REJECTED' AND granted_amount IS NULL AND rejection_ground IS NOT NULL)
        ),
    CONSTRAINT ck_decision_motivation
        CHECK (LENGTH(TRIM(motivation)) > 0)
);

-- -----------------------------------------------------------------------------
-- Audit trail: append-only history of what happened, who did it, and when.
-- -----------------------------------------------------------------------------
CREATE TABLE audit_event (
    id                   BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    grant_application_id UUID,
    event_type           VARCHAR(50)  NOT NULL,
    actor_oid            VARCHAR(64)  NOT NULL,
    actor_name           VARCHAR(200),
    occurred_at          TIMESTAMPTZ  NOT NULL,
    details              JSONB,

    CONSTRAINT fk_audit_event_application
        FOREIGN KEY (grant_application_id) REFERENCES grant_application (id)
);

CREATE INDEX ix_audit_event_application ON audit_event (grant_application_id, occurred_at);
